import{_ as i,o as a,c as t,a3 as r}from"./chunks/framework.1Y430-yj.js";const b=JSON.parse('{"title":"Error Propagation in Serial Structures","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"串联结构的误差传播","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=LbIb8qSMuIb0YhWSlQiP1F","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-LbIb8qSMuIb0YhWSlQiP1F.md","filePath":"logistics/src/page-LbIb8qSMuIb0YhWSlQiP1F.md","lastUpdated":null}'),_={name:"logistics/src/page-LbIb8qSMuIb0YhWSlQiP1F.md"};function o(p,e,s,n,l,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="串联结构的误差传播" aria-hidden="true"></span><h1 id="error-propagation-in-serial-structures" tabindex="-1">Error Propagation in Serial Structures <a class="header-anchor" href="#error-propagation-in-serial-structures" aria-label="Permalink to &quot;Error Propagation in Serial Structures&quot;">​</a></h1><blockquote><p>Source page ID: <code>LbIb8qSMuIb0YhWSlQiP1F</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=LbIb8qSMuIb0YhWSlQiP1F" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Theorem: if sequences a and b are connected in series, with b&#39;s output triggering a&#39;s input, generating sequence c, then:</p><p>M_dev^c &lt;= M_dev^a + T_ideal^a * M_dev^b.</p><p>Proof:</p><p>Let a&#39;s 1-position sequence be {t_i^a}{i=1}^{K_a}, with ideal interval T_ideal^a = L_a/K_a;</p><p>and b&#39;s be {t_i^b}{i=1}^{K_b}, with T_ideal^b = L_b/K_b.</p><p>After series connection, c&#39;s ith 1 lies at a&#39;s t_i^b-th 1:</p><p>t_i^c = t_{t_i^b}^a.</p><p>Also K_c = K_b and T_ideal^c = T_ideal^a * T_ideal^b.</p><p>The ith output error of c is:</p><p>E_c(i) = t_i^c - i * T_ideal^c</p><p>= t_{t_i^b}^a - i * T_ideal^a * T_ideal^b</p><p>= [E_a(t_i^b) + t_i^b * T_ideal^a] - i * T_ideal^a * T_ideal^b</p><p>= E_a(t_i^b) + (t_i^b - i * T_ideal^b) * T_ideal^a</p><p>= E_a(t_i^b) + E_b(i) * T_ideal^a.</p><p>Therefore:</p><p>max_i E_c(i) &lt;= max_j E_a(j) + T_ideal^a * max_i E_b(i)</p><p>min_i E_c(i) &gt;= min_j E_a(j) + T_ideal^a * min_i E_b(i).</p><p>Subtracting gives:</p><p>M_dev^c &lt;= M_dev^a + T_ideal^a * M_dev^b.</p><p>Proof by jnk; correctness not reviewed by anyone; standardized terminology by jnk.</p></div>',1)])])}const u=i(_,[["render",o]]);export{b as __pageData,u as default};
